import {sanitize,parseHTML,textToHTML} from './book-tools.mjs';
import {buildPDFChapters,rebuildPDFSources,splitHTMLChapters,countHeadings,parsePageSelection} from './structure.mjs';
import {importFile,blobAsDataURL} from './importers.mjs';
export function installEditionUI({getBook,applyBook,toast}){
    const $=id=>document.getElementById(id);let coverDraft=null,coverChoices=[],pagesDraft=[],chapterDraft=[];
    function renderCover(){const b=getBook();$('coverthumbnail').hidden=!b.cover;$('coverplaceholder').hidden=Boolean(b.cover);if(b.cover)$('coverthumbnail').src=b.cover.data;else $('coverthumbnail').removeAttribute('src');$('coverstatus').textContent=b.cover?'Capa definida':'Sem capa';$('sourcecount').textContent=(b.sources||[]).reduce((n,s)=>n+s.pages.filter(p=>!p.excluded).length,0)+' páginas de PDF';}
    function coverPreview(){const image=$('coverdraft');image.hidden=!coverDraft;if(coverDraft)image.src=coverDraft.data;else image.removeAttribute('src');$('coverdraftstatus').textContent=coverDraft?.name||'O EPUB será criado sem uma capa adicional.';}
    $('covermanager').onclick=()=>{const b=getBook();coverDraft=b.cover?structuredClone(b.cover):null;coverChoices=[];
        for(const c of [b.cover,...b.coverOptions||[]].filter(Boolean))if(!coverChoices.some(x=>x.data===c.data))coverChoices.push(c);
        for(const chapter of b.chapters)for(const img of parseHTML(chapter.html).querySelectorAll('img')){const data=img.getAttribute('src');if(data?.startsWith('data:image/')&&!coverChoices.some(x=>x.data===data))coverChoices.push({data,name:'Imagem de '+chapter.name,kind:'original'});if(coverChoices.length>=50)break;}
        $('coverchoices').replaceChildren();const none=document.createElement('option');none.value='';none.textContent='Selecione uma capa ou imagem do livro';$('coverchoices').append(none);coverChoices.forEach((c,i)=>{const o=document.createElement('option');o.value=i;o.textContent=c.name;$('coverchoices').append(o);});coverPreview();$('coverdialog').showModal();
    };
    $('coverchoices').onchange=()=>{if($('coverchoices').value!=='')coverDraft=coverChoices[Number($('coverchoices').value)];coverPreview();};
    $('choosecover').onclick=()=>$('coverfile').click();$('coverfile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{
        if(f.size>15*1024*1024)throw Error('Selecione uma imagem de até 15 MB.');
        const data=await blobAsDataURL(f),image=new Image();image.src=data;await image.decode();
        const scale=Math.min(1,1600/image.width,2400/image.height),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);
        coverDraft={data:canvas.toDataURL('image/jpeg',.92),name:f.name,kind:'custom'};coverPreview();
    }catch(err){toast('Capa: '+err.message);}finally{e.target.value='';}};
    $('clearcover').onclick=()=>{coverDraft=null;coverPreview();};$('applycover').onclick=()=>{const b=structuredClone(getBook());b.cover=coverDraft;b.coverOptions||=[];if(coverDraft&&!b.coverOptions.some(c=>c.data===coverDraft.data))b.coverOptions.push(coverDraft);applyBook(b);$('coverdialog').close();toast('Capa atualizada. Ela será identificada como capa nos metadados do EPUB.');};
    function previewChapters(){const b=getBook(),allHeadings=$('chaptermethod').value==='all';chapterDraft=b.chapters.flatMap(c=>splitHTMLChapters(c.html,{name:c.name,allHeadings}).map((piece,i)=>({...c,...piece,id:i===0?c.id:crypto.randomUUID()})));$('chapterresult').textContent=`${b.chapters.length} seções atuais → ${chapterDraft.length} seções propostas · ${countHeadings(chapterDraft)} títulos preservados`;$('chapterlist').replaceChildren();chapterDraft.forEach(c=>{const li=document.createElement('li');li.textContent=c.name;$('chapterlist').append(li);});}
    $('chaptermanager').onclick=()=>{previewChapters();$('chapterdialog').showModal();};$('chaptermethod').onchange=previewChapters;$('applychapters').onclick=()=>{const b=structuredClone(getBook());b.chapters=chapterDraft;applyBook(b);$('chapterdialog').close();toast('Divisão de capítulos atualizada. Confira o sumário antes de exportar.');};
    const currentSource=()=>pagesDraft.find(s=>s.id===$('pagesource').value);
    function renderSources(selected){$('pagesource').replaceChildren();for(const source of pagesDraft){const o=document.createElement('option');o.value=source.id;o.textContent=source.name;$('pagesource').append(o);}if(selected)$('pagesource').value=selected;renderPages();}
    function renderPages(){const source=currentSource();$('pagelist').replaceChildren();$('pageafter').replaceChildren();const beginning=document.createElement('option');beginning.value='-1';beginning.textContent='No início';$('pageafter').append(beginning);
        if(!source){$('pagesummary').textContent='Sem PDF de origem. Você pode inserir uma nova seção ou importar PDFs.';$('applypages').disabled=true;return;}
        $('applypages').disabled=false;$('pagecleanmargins').checked=source.removeMargins!==false;
        source.pages.forEach((p,i)=>{const row=document.createElement('div');row.className='pagerow'+(p.excluded?' excluded':'');const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=!p.excluded;check.onchange=()=>{p.excluded=!check.checked;renderPages();};
            const snippet=p.manualHTML!==undefined?parseHTML(p.manualHTML).body.textContent:(p.lines||[]).map(l=>l.text).join(' ');label.append(check,document.createTextNode(` ${i+1}. ${p.title||p.origin||source.name}${p.number?' · original '+p.number:''}`));const text=document.createElement('small');text.textContent=snippet.slice(0,160)||'Página em branco';row.append(label,text);
            for(const [delta,symbol]of [[-1,'↑'],[1,'↓']]){const btn=document.createElement('button');btn.textContent=symbol;btn.title='Mover página '+(delta<0?'para cima':'para baixo');btn.disabled=i+delta<0||i+delta>=source.pages.length;btn.onclick=()=>{[source.pages[i],source.pages[i+delta]]=[source.pages[i+delta],source.pages[i]];renderPages();};row.append(btn);}
            if(p.manualHTML!==undefined){const edit=document.createElement('button');edit.textContent='Editar texto';edit.onclick=()=>{const value=prompt('Texto desta página',parseHTML(p.manualHTML).body.textContent);if(value!==null){p.manualHTML=textToHTML(value,{reconstruct:false});renderPages();}};row.append(edit);}
            $('pagelist').append(row);const o=document.createElement('option');o.value=i;o.textContent='Depois da página '+(i+1);$('pageafter').append(o);
        });
        const generated=buildPDFChapters(source);$('pagesummary').textContent=`${source.pages.filter(p=>!p.excluded).length}/${source.pages.length} páginas incluídas · ${generated.chapters.length} seções propostas`;
    }
    $('pagesmanager').onclick=()=>{pagesDraft=structuredClone(getBook().sources||[]);renderSources();$('pagesdialog').showModal();};$('pagesource').onchange=renderPages;$('pagecleanmargins').onchange=()=>{const s=currentSource();if(s)s.removeMargins=$('pagecleanmargins').checked;renderPages();};
    $('excludepages').onclick=()=>{try{const source=currentSource();if(!source)throw Error('Importe um PDF primeiro.');const selection=parsePageSelection($('pagerange').value,source.pages.length);if(!selection.length)throw Error('Informe as páginas a excluir.');selection.forEach(i=>source.pages[i].excluded=true);renderPages();}catch(e){toast(e.message);}};
    function ensureSource(){let source=currentSource();if(!source){source={id:crypto.randomUUID(),name:'Páginas adicionadas',pages:[],outline:[],removeMargins:true};pagesDraft.push(source);renderSources(source.id);}return source;}
    $('inserttextpage').onclick=()=>{const source=ensureSource(),after=Number($('pageafter').value),title=$('newpagetitle').value.trim()||'Nova página';source.pages.splice(after+1,0,{id:crypto.randomUUID(),title,origin:'Texto inserido',manualHTML:'<h1>'+title.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))+'</h1>'+textToHTML($('newpagetext').value,{reconstruct:false}),lines:[],height:800,width:600,excluded:false});renderPages();$('newpagetext').value='';};
    $('insertpdfpages').onclick=()=>$('pagepdffile').click();$('pagepdffile').onchange=async e=>{const files=[...e.target.files];if(!files.length)return;const btn=$('insertpdfpages');btn.disabled=true;try{const source=ensureSource();let after=Number($('pageafter').value);for(const file of files){const imported=await importFile(file,message=>{btn.textContent=message;});for(const part of imported.sources||[]){source.pages.splice(after+1,0,...part.pages);after+=part.pages.length;source.outline.push(...part.outline);}}renderPages();}catch(err){toast(err.message);}finally{btn.disabled=false;btn.textContent='Inserir páginas de PDF';e.target.value='';}};
    $('applypages').onclick=()=>{try{const b=getBook(),next=rebuildPDFSources(b,pagesDraft);applyBook(next);$('pagesdialog').close();toast('Páginas atualizadas e capítulos reconstruídos.');}catch(err){toast(err.message);}};
    $('addlogicalpage').onclick=()=>{const b=structuredClone(getBook());b.chapters.push({id:crypto.randomUUID(),name:'Nova seção',html:'<h1>Nova seção</h1><p><br></p>'});applyBook(b,b.chapters.length-1);$('pagesdialog').close();};
    return {render:renderCover};
}

